CREATE TABLE IF NOT EXISTS guild_schema_migrations (version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS guild_tenants (id uuid PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, mode text NOT NULL CHECK (mode IN ('judge','owner')));
CREATE TABLE IF NOT EXISTS guild_sessions (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES guild_tenants(id), token_hash text NOT NULL UNIQUE, role text NOT NULL CHECK (role IN ('judge','owner','provider','operator')), expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS guild_commissions (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES guild_tenants(id), revision integer NOT NULL DEFAULT 0, state text NOT NULL, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS guild_commissions_tenant ON guild_commissions(tenant_id, created_at DESC);
CREATE TABLE IF NOT EXISTS guild_commands (tenant_id uuid NOT NULL REFERENCES guild_tenants(id), command_id uuid NOT NULL, commission_id uuid, payload_hash text NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id, command_id));
CREATE TABLE IF NOT EXISTS guild_artifacts (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES guild_tenants(id), commission_id uuid NOT NULL REFERENCES guild_commissions(id), package_id text NOT NULL, content_hash text NOT NULL, manifest jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(commission_id,package_id,content_hash));
CREATE TABLE IF NOT EXISTS guild_acceptance_decisions (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES guild_tenants(id), commission_id uuid NOT NULL REFERENCES guild_commissions(id), package_id text NOT NULL, contract_version integer NOT NULL, artifact_id uuid NOT NULL REFERENCES guild_artifacts(id), artifact_hash text NOT NULL, criteria_digest text NOT NULL, actor_id uuid NOT NULL, decision text NOT NULL, review_disclosures jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(commission_id,package_id,contract_version));
CREATE TABLE IF NOT EXISTS guild_events (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES guild_tenants(id), commission_id uuid NOT NULL REFERENCES guild_commissions(id), sequence integer NOT NULL, event_type text NOT NULL, event jsonb NOT NULL, previous_hash text, event_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(commission_id,sequence));
CREATE TABLE IF NOT EXISTS guild_jobs (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES guild_tenants(id), commission_id uuid NOT NULL REFERENCES guild_commissions(id), business_key text NOT NULL, type text NOT NULL, state text NOT NULL DEFAULT 'queued', input jsonb NOT NULL, output jsonb, attempts integer NOT NULL DEFAULT 0, lease_until timestamptz, available_at timestamptz NOT NULL DEFAULT now(), error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,business_key));
CREATE INDEX IF NOT EXISTS guild_jobs_dispatch ON guild_jobs(state,available_at);
CREATE TABLE IF NOT EXISTS guild_model_runs (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES guild_tenants(id), job_id uuid NOT NULL REFERENCES guild_jobs(id), provider text NOT NULL, model text NOT NULL, prompt_version text NOT NULL, input_hash text NOT NULL, output_hash text, output jsonb, status text NOT NULL, latency_ms integer, usage jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS guild_budget_reservations (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES guild_tenants(id), commission_id uuid NOT NULL REFERENCES guild_commissions(id), mandate_id text NOT NULL, operation_key text NOT NULL, amount_minor bigint NOT NULL CHECK(amount_minor>=0), currency text NOT NULL CHECK(currency='USD'), state text NOT NULL CHECK(state IN ('reserved','committed','released','expired')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,operation_key));
CREATE TABLE IF NOT EXISTS guild_approval_challenges (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES guild_tenants(id), commission_id uuid NOT NULL REFERENCES guild_commissions(id), revision integer NOT NULL, digest text NOT NULL, expires_at timestamptz NOT NULL, consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS guild_rate_limits (bucket text PRIMARY KEY, window_start timestamptz NOT NULL, count integer NOT NULL);
INSERT INTO guild_schema_migrations(version) VALUES(1) ON CONFLICT DO NOTHING;
